/*
 * Zephyr ADC example for nrf52840dk
 *
 * This application configures ADC channel 0 with hardware oversampling
 * (2^4 = 16 samples) and continuously prints the averaged result every
 * second.
 */

#include <zephyr/kernel.h>
#include <zephyr/device.h>
#include <zephyr/drivers/adc.h>

int main(void)
{
    /* Get ADC device using the alias defined in the devicetree */
    const struct device *adc_dev = DEVICE_DT_GET(DT_ALIAS(adc0));

    if (!device_is_ready(adc_dev)) {
        printk("ADC device is not ready!\n");
        return -ENODEV;
    }

    /* Configure ADC channel 0 */
    struct adc_channel_cfg channel_cfg = {
        .gain             = ADC_GAIN_1,
        .reference        = ADC_REF_INTERNAL,
        .acquisition_time = ADC_ACQ_TIME_DEFAULT,
        .channel_id       = 0,
    };

    int ret = adc_channel_setup(adc_dev, &channel_cfg);
    if (ret != 0) {
        printk("adc_channel_setup failed (%d)\n", ret);
        return ret;
    }

    /* Sample buffer */
    static int16_t sample_buf[1];

    /* Configure ADC sequence */
    struct adc_sequence seq = {
        .channels      = BIT(0),        /* channel 0 */
        .buffer        = sample_buf,
        .buffer_size   = sizeof(sample_buf),
        .resolution    = 12,            /* 12‑bit resolution */
        .oversampling  = 4,             /* 2^4 = 16 samples */
        /* All other fields are zero by default */
    };

    /* Continuous read loop */
    while (1) {
        ret = adc_read(adc_dev, &seq);
        if (ret == 0) {
            printk("Sample: %d\n", sample_buf[0]);
        } else {
            printk("ADC read error: %d\n", ret);
        }

        k_msleep(1000); /* Sleep 1 second between reads */
    }

    return 0;
}
